import pandas as pd
from pypdf import PdfReader

print("--- Purchase Orders ---")
try:
    df_po = pd.read_csv('/root/purchase_orders.csv')
    print(df_po.head())
    print(df_po.columns.tolist())
except Exception as e:
    print(e)

print("\n--- Vendors ---")
try:
    df_vendors = pd.read_excel('/root/vendors.xlsx')
    print(df_vendors.head())
    print(df_vendors.columns.tolist())
except Exception as e:
    print(e)

print("\n--- Invoice Page 1 ---")
try:
    reader = PdfReader('/root/invoices.pdf')
    if len(reader.pages) > 0:
        print(reader.pages[0].extract_text())
except Exception as e:
    print(e)

